mapper.insert:
INSERT INTO mt_reply_knowledge_document (
    shop_id, file_name, file_type, file_size, storage_provider, object_key,
    parse_status, parse_error, chunk_count, enabled, deleted, create_time, update_time
) VALUES (
    #{shopId}, #{fileName}, #{fileType}, #{fileSize}, #{storageProvider}, #{objectKey},
    #{parseStatus}, #{parseError}, #{chunkCount}, #{enabled}, #{deleted}, #{createTime}, #{updateTime}
)

mapper.update:
UPDATE mt_reply_knowledge_document
SET parse_status = #{parseStatus},
    parse_error = #{parseError},
    chunk_count = #{chunkCount},
    update_time = #{updateTime}
