UPDATE mt_reply_knowledge_document
SET deleted = 1,
    enabled = 0,
    update_time = #{updateTime}
WHERE id = #{id}
  AND shop_id = #{shopId}

UPDATE mt_reply_knowledge_document
SET deleted = 1,
    enabled = 0,
    update_time = #{updateTime}
WHERE shop_id = #{shopId}
  AND deleted = 0
